class Solution {
public:
    string evaluate(string s, vector<vector<string>>& knowledge) {
        unordered_map<string, string> dict;
        for (const auto& pair : knowledge) {
            dict[pair[0]] = pair[1];
        }
        string res = "", key = "";
        bool inBracket = false;
        for (char c : s) {
            if (c == '(') {
                inBracket = true;
                key.clear();
            } else if (c == ')') {
                inBracket = false;
                auto it = dict.find(key);
                res += (it != dict.end()) ? it->second : "?";
            } else if (inBracket) {
                key += c;
            } else {
                res += c;
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String evaluate(String s, List<List<String>> knowledge) {
        Map<String, String> dict = new HashMap<>();
        for (List<String> pair : knowledge) {
            dict.put(pair.get(0), pair.get(1));
        }
        StringBuilder res = new StringBuilder();
        StringBuilder key = new StringBuilder();
        boolean inBracket = false;
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            if (c == '(') {
                inBracket = true;
                key.setLength(0);
            } else if (c == ')') {
                inBracket = false;
                res.append(dict.getOrDefault(key.toString(), "?"));
            } else if (inBracket) {
                key.append(c);
            } else {
                res.append(c);
            }
        }
        return res.toString();
    }
}

/**
 * @param {string} s
 * @param {string[][]} knowledge
 * @return {string}
 */
var evaluate = function(s, knowledge) {
    const dict = new Map();
    for (const [k, v] of knowledge) {
        dict.set(k, v);
    }
    return s.replace(/\(([a-z]+)\)/g, (_, key) => dict.get(key) ?? '?');
};
